//! `WcsMap::get_pv` gives the values C's `astGetPV` gives (wcsmap.c
//! `GetPV`): the defaults of unset latitude parameters, the longitude
//! parameters 0 to 2 defaulted from the native reference point except for
//! TPN, a bad value for an unset parameter without a default, and
//! `AST__AXIIN` for an invalid axis or parameter index.
//!
//! `wcsmap_pv_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/wcsmap_pv_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "wcsmap_pv_oracle/cases.rs"]
mod cases;

use ast_core::error::ErrorCode;
use ast_core::mappings::{WcsMap, WcsProjection};

#[test]
fn get_pv_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(name, code, settings, axis, m, want) in cases::CASES {
        let proj = WcsProjection::from_code(code).expect("a projection type");
        let mut map = WcsMap::new(2, proj, 1, 2).unwrap();
        for setting in settings.split(',').map(str::trim).filter(|s| !s.is_empty()) {
            let (key, value) = setting.split_once('=').expect("PVi_m=value");
            let (i, k) = key.trim_start_matches("PV").split_once('_').expect("PVi_m");
            map.set_pv(
                i.parse().unwrap(),
                k.parse().unwrap(),
                value.parse().unwrap(),
            )
            .unwrap();
        }
        let got = map.get_pv(axis, m);
        let ok = match (&got, want) {
            (Ok(v), Some(w)) => v.to_bits() == w.to_bits(),
            (Err(e), None) => e.code() == ErrorCode::Axiin,
            _ => false,
        };
        if !ok {
            failures.push(format!("{name}: {got:?}, C gives {want:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// `test_pv` reports only parameters that were set.
#[test]
fn test_pv_reports_set_parameters() {
    let mut map = WcsMap::new(2, WcsProjection::Cop, 1, 2).unwrap();
    assert!(!map.test_pv(2, 1));
    map.set_pv(2, 1, 45.0).unwrap();
    assert!(map.test_pv(2, 1));
    assert!(!map.test_pv(1, 1));
}
